const main = items[0].json;

const output = {
  time: main.meta.triggered_at,
  crop: main.crop ?? null,
  sensors: (main.sensors ?? []).map(s => ({
    type:  s.type,
    value: s.value
  }))
};

return [{ json: output }];

const raw      = JSON.parse($input.first().json.output);
const mainJson = { ...$('Final_Decisions').first().json };

// ─── Merge sensor descriptions ────────────────────────────────────────────────

const descriptionMap = {};
raw.forEach(s => {
  descriptionMap[s.type.toLowerCase()] = s.description;
});

mainJson.sensors = mainJson.sensors.map(s => ({
  ...s,
  description: descriptionMap[s.type.toLowerCase()] ?? s.description
}));

return [{ json: mainJson }];

